def maxEnvelopes(envelopes: list[list[int]]) -> int:
    import bisect
    # Sort ascending by width, descending by height for ties
    envelopes.sort(key=lambda x: (x[0], -x[1]))
    tails = []
    for _, h in envelopes:
        idx = bisect.bisect_left(tails, h)
        if idx == len(tails):
            tails.append(h)
        else:
            tails[idx] = h
    return len(tails)

